impl Account {
    pub fn transfer_to(&mut self, target: &mut Account, amount: f64) -> Result<(), InsufficientFunds> {
        if self.balance < amount {
            return Err(InsufficientFunds);
        }
        self.balance -= amount;
        target.balance += amount;
        Ok(())
    }
}
